from taf.gnb.oam.coam.cu.schemas.base import SchemaField, SchemaObject


class BTSInfoASMV1(SchemaObject):
    status = SchemaField(name="operational_state", not_null=True)
    name = SchemaField(name="name", not_null=True)
    bts_id = SchemaField(name="mrbts_id", not_null=True)
    number_of_alarms = SchemaField(name="number_of_alarms", not_null=True)

    def __init__(self, status=None, name=None, bts_id=None, number_of_alarms=None):
        self.status = status
        self.name = name
        self.bts_id = bts_id
        self.number_of_alarms = number_of_alarms

        super(BTSInfoASMV1, self).__init__()
